pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate) public {
        // 1. bound to admissible range (validate <= 5000)
        _feeRate = uint16(bound(_feeRate, 0, 5000));
        // 2. vm.prank to call initialize as the factory owner
        vm.startPrank(address(this));
        c.initialize(address(0), address(0), 0, 0, 0, _feeRate, bytes32(0), false, false);
        vm.stopPrank();
        // 3. assert that feeRate equals the passed argument
        assertEq(c.feeRate(), _feeRate);
    }
}

